CREATE TABLE "places" ("id" TEXT NOT NULL, "place_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_definition_steps" ("id" TEXT NOT NULL, "definition_id" TEXT NOT NULL REFERENCES preparation_definitions (id), "name" TEXT NOT NULL, "minutes" INTEGER NOT NULL CHECK (minutes >= 0), "position" INTEGER NOT NULL CHECK (position >= 0), PRIMARY KEY ("id"), UNIQUE ("definition_id", "position"));
CREATE TABLE "preparation_definitions" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL, "scope" TEXT NOT NULL, "name" TEXT NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_schedules" ("id" TEXT NOT NULL, "schedule_id" TEXT NOT NULL REFERENCES schedules (id), "preparation_name" TEXT NOT NULL, "preparation_time" INTEGER NOT NULL, "next_preparation_id" TEXT NULL REFERENCES preparation_schedules (id), PRIMARY KEY ("id"));
CREATE TABLE "preparation_template_steps" ("id" TEXT NOT NULL, "template_id" TEXT NOT NULL REFERENCES preparation_templates (id), "preparation_name" TEXT NOT NULL, "preparation_time" INTEGER NOT NULL, "position" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_templates" ("id" TEXT NOT NULL, "template_name" TEXT NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "preparation_users" ("id" TEXT NOT NULL, "user_id" TEXT NOT NULL REFERENCES users (id), "preparation_name" TEXT NOT NULL, "preparation_time" INTEGER NOT NULL, "next_preparation_id" TEXT NULL REFERENCES preparation_users (id), PRIMARY KEY ("id"));
CREATE TABLE "recurring_schedule_exclusions" ("segment_id" TEXT NOT NULL REFERENCES recurring_schedule_segments (id), "slot_key" TEXT NOT NULL, "ordinal" INTEGER NOT NULL, PRIMARY KEY ("segment_id", "slot_key"));
CREATE TABLE "recurring_schedule_segments" ("root_segment_id" TEXT NULL, "aggregate_incarnation" TEXT NULL, "aggregate_version" INTEGER NULL, "last_mutation_id" TEXT NULL, "last_mutation_digest" TEXT NULL, "last_mutation_version" INTEGER NULL, "id" TEXT NOT NULL, "series_id" TEXT NOT NULL, "rule_json" TEXT NOT NULL, "schedule_json" TEXT NOT NULL, "preparation_id" TEXT NOT NULL REFERENCES preparation_definitions (id), "from_slot" TEXT NOT NULL, "before_slot" TEXT NULL, "created_at" INTEGER NOT NULL, "preparation_not_before" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "schedules" ("aggregate_incarnation" TEXT NULL, "aggregate_version" INTEGER NULL, "last_mutation_id" TEXT NULL, "last_mutation_digest" TEXT NULL, "last_mutation_version" INTEGER NULL, "id" TEXT NOT NULL, "place_id" TEXT NOT NULL REFERENCES places (id), "schedule_name" TEXT NOT NULL, "time_zone_id" TEXT NOT NULL DEFAULT 'UTC', "occurrence_offset_seconds" INTEGER NULL, "schedule_time" TEXT NOT NULL, "move_time" INTEGER NOT NULL, "is_changed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_changed" IN (0, 1)), "is_started" INTEGER NOT NULL DEFAULT 0 CHECK ("is_started" IN (0, 1)), "schedule_spare_time" INTEGER NULL, "schedule_note" TEXT NULL, "lateness_time" INTEGER NOT NULL DEFAULT -1, "done_status" TEXT NOT NULL DEFAULT 'notEnded', "started_at" INTEGER NULL, "finished_at" INTEGER NULL, "preparation_mode" TEXT NULL, "preparation_template_id" TEXT NULL, "preparation_template_name" TEXT NULL, "preparation_template_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("preparation_template_deleted" IN (0, 1)), "preparation_frozen" INTEGER NOT NULL DEFAULT 0 CHECK ("preparation_frozen" IN (0, 1)), "score_contribution_recorded" INTEGER NOT NULL DEFAULT 0 CHECK ("score_contribution_recorded" IN (0, 1)), "recurring_segment_id" TEXT NULL, "recurring_slot_key" TEXT NULL, "recurring_ordinal" INTEGER NULL, "recurring_overrides" TEXT NOT NULL DEFAULT '', "preparation_definition_id" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "users" ("store_incarnation" TEXT NULL, "id" TEXT NOT NULL, "spare_time" INTEGER NOT NULL, "note" TEXT NOT NULL, "is_onboarding_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_onboarding_completed" IN (0, 1)), "eligible_outcome_count" INTEGER NOT NULL DEFAULT 0, "on_time_outcome_count" INTEGER NOT NULL DEFAULT 0, "alarms_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("alarms_enabled" IN (0, 1)), "alarm_offset_minutes" INTEGER NOT NULL DEFAULT 0, "detailed_notification_content" INTEGER NOT NULL DEFAULT 0 CHECK ("detailed_notification_content" IN (0, 1)), "data_revision" INTEGER NOT NULL DEFAULT 0, "last_exported_revision" INTEGER NULL, "last_exported_at" INTEGER NULL, "first_durable_data_at" INTEGER NULL, "last_durable_data_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX preparation_schedules_next_preparation_id_idx ON preparation_schedules (next_preparation_id);
CREATE INDEX preparation_schedules_schedule_id_idx ON preparation_schedules (schedule_id);
CREATE INDEX preparation_template_steps_template_id_idx ON preparation_template_steps (template_id);
CREATE INDEX preparation_users_next_preparation_id_idx ON preparation_users (next_preparation_id);
CREATE INDEX preparation_users_user_id_idx ON preparation_users (user_id);
CREATE INDEX schedules_place_id_idx ON schedules (place_id);
CREATE INDEX schedules_schedule_time_idx ON schedules (schedule_time);
CREATE TRIGGER definition_steps_delete AFTER DELETE ON preparation_definition_steps BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_definition_id=OLD.definition_id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_definition_id=OLD.definition_id); UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT root_segment_id FROM recurring_schedule_segments WHERE preparation_id=OLD.definition_id); END;
CREATE TRIGGER definition_steps_insert AFTER INSERT ON preparation_definition_steps BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_definition_id=NEW.definition_id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_definition_id=NEW.definition_id); UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT root_segment_id FROM recurring_schedule_segments WHERE preparation_id=NEW.definition_id); END;
CREATE TRIGGER definition_steps_update AFTER UPDATE ON preparation_definition_steps BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_definition_id=NEW.definition_id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_definition_id=NEW.definition_id); UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT root_segment_id FROM recurring_schedule_segments WHERE preparation_id=NEW.definition_id); END;
CREATE TRIGGER exclusion_delete AFTER DELETE ON recurring_schedule_exclusions BEGIN UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = OLD.segment_id); END;
CREATE TRIGGER exclusion_insert AFTER INSERT ON recurring_schedule_exclusions BEGIN UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = NEW.segment_id); END;
CREATE TRIGGER exclusion_update AFTER UPDATE ON recurring_schedule_exclusions BEGIN UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = NEW.segment_id); END;
CREATE TRIGGER place_version AFTER UPDATE OF place_name ON places WHEN NEW.place_name IS NOT OLD.place_name BEGIN
    UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE place_id = NEW.id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.place_id=NEW.id); END;
CREATE TRIGGER preparation_default_delete AFTER DELETE ON preparation_users BEGIN
      UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE preparation_definition_id IS NULL AND NOT EXISTS (SELECT 1 FROM preparation_schedules p WHERE p.schedule_id=schedules.id) AND NOT EXISTS (SELECT 1 FROM preparation_templates p WHERE p.id=schedules.preparation_template_id AND schedules.preparation_template_deleted=0); UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_definition_id IS NULL AND NOT EXISTS (SELECT 1 FROM preparation_schedules p WHERE p.schedule_id=s.id) AND NOT EXISTS (SELECT 1 FROM preparation_templates p WHERE p.id=s.preparation_template_id AND s.preparation_template_deleted=0)); END;
CREATE TRIGGER preparation_default_insert AFTER INSERT ON preparation_users BEGIN
      UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE preparation_definition_id IS NULL AND NOT EXISTS (SELECT 1 FROM preparation_schedules p WHERE p.schedule_id=schedules.id) AND NOT EXISTS (SELECT 1 FROM preparation_templates p WHERE p.id=schedules.preparation_template_id AND schedules.preparation_template_deleted=0); UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_definition_id IS NULL AND NOT EXISTS (SELECT 1 FROM preparation_schedules p WHERE p.schedule_id=s.id) AND NOT EXISTS (SELECT 1 FROM preparation_templates p WHERE p.id=s.preparation_template_id AND s.preparation_template_deleted=0)); END;
CREATE TRIGGER preparation_default_update AFTER UPDATE ON preparation_users BEGIN
      UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE preparation_definition_id IS NULL AND NOT EXISTS (SELECT 1 FROM preparation_schedules p WHERE p.schedule_id=schedules.id) AND NOT EXISTS (SELECT 1 FROM preparation_templates p WHERE p.id=schedules.preparation_template_id AND schedules.preparation_template_deleted=0); UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_definition_id IS NULL AND NOT EXISTS (SELECT 1 FROM preparation_schedules p WHERE p.schedule_id=s.id) AND NOT EXISTS (SELECT 1 FROM preparation_templates p WHERE p.id=s.preparation_template_id AND s.preparation_template_deleted=0)); END;
CREATE TRIGGER preparation_schedule_delete AFTER DELETE ON preparation_schedules BEGIN
      UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = OLD.schedule_id;
      UPDATE recurring_schedule_segments SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = (SELECT recurring_segment_id FROM schedules WHERE id = OLD.schedule_id)); END;
CREATE TRIGGER preparation_schedule_insert AFTER INSERT ON preparation_schedules BEGIN
      UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = NEW.schedule_id;
      UPDATE recurring_schedule_segments SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = (SELECT recurring_segment_id FROM schedules WHERE id = NEW.schedule_id)); END;
CREATE TRIGGER preparation_schedule_update AFTER UPDATE ON preparation_schedules BEGIN
      UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = NEW.schedule_id;
      UPDATE recurring_schedule_segments SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = (SELECT recurring_segment_id FROM schedules WHERE id = NEW.schedule_id)); END;
CREATE TRIGGER recurring_schedule_segments_identity AFTER INSERT ON recurring_schedule_segments
      WHEN NEW.aggregate_incarnation IS NULL BEGIN
      UPDATE recurring_schedule_segments SET aggregate_incarnation = lower(hex(randomblob(16))), aggregate_version = 0 WHERE id = NEW.id; END;
CREATE TRIGGER schedules_deleted AFTER DELETE ON schedules BEGIN
    UPDATE recurring_schedule_segments SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = OLD.recurring_segment_id); END;
CREATE TRIGGER schedules_identity AFTER INSERT ON schedules
      WHEN NEW.aggregate_incarnation IS NULL BEGIN
      UPDATE schedules SET aggregate_incarnation = lower(hex(randomblob(16))), aggregate_version = 0 WHERE id = NEW.id; END;
CREATE TRIGGER schedules_version AFTER UPDATE OF place_id,schedule_name,time_zone_id,occurrence_offset_seconds,schedule_time,move_time,is_changed,is_started,schedule_spare_time,schedule_note,lateness_time,done_status,started_at,finished_at,preparation_mode,preparation_template_id,preparation_template_name,preparation_template_deleted,preparation_frozen,score_contribution_recorded,recurring_segment_id,recurring_slot_key,recurring_ordinal,recurring_overrides,preparation_definition_id ON schedules
    WHEN NEW.place_id IS NOT OLD.place_id OR NEW.schedule_name IS NOT OLD.schedule_name OR NEW.time_zone_id IS NOT OLD.time_zone_id OR NEW.occurrence_offset_seconds IS NOT OLD.occurrence_offset_seconds OR NEW.schedule_time IS NOT OLD.schedule_time OR NEW.move_time IS NOT OLD.move_time OR NEW.is_changed IS NOT OLD.is_changed OR NEW.is_started IS NOT OLD.is_started OR NEW.schedule_spare_time IS NOT OLD.schedule_spare_time OR NEW.schedule_note IS NOT OLD.schedule_note OR NEW.lateness_time IS NOT OLD.lateness_time OR NEW.done_status IS NOT OLD.done_status OR NEW.started_at IS NOT OLD.started_at OR NEW.finished_at IS NOT OLD.finished_at OR NEW.preparation_mode IS NOT OLD.preparation_mode OR NEW.preparation_template_id IS NOT OLD.preparation_template_id OR NEW.preparation_template_name IS NOT OLD.preparation_template_name OR NEW.preparation_template_deleted IS NOT OLD.preparation_template_deleted OR NEW.preparation_frozen IS NOT OLD.preparation_frozen OR NEW.score_contribution_recorded IS NOT OLD.score_contribution_recorded OR NEW.recurring_segment_id IS NOT OLD.recurring_segment_id OR NEW.recurring_slot_key IS NOT OLD.recurring_slot_key OR NEW.recurring_ordinal IS NOT OLD.recurring_ordinal OR NEW.recurring_overrides IS NOT OLD.recurring_overrides OR NEW.preparation_definition_id IS NOT OLD.preparation_definition_id BEGIN
    UPDATE schedules SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = NEW.id;
    UPDATE recurring_schedule_segments SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = OLD.recurring_segment_id); END;
CREATE TRIGGER segment_root AFTER INSERT ON recurring_schedule_segments WHEN NEW.root_segment_id IS NULL BEGIN UPDATE recurring_schedule_segments SET root_segment_id = COALESCE((SELECT root_segment_id FROM recurring_schedule_segments WHERE series_id=NEW.series_id AND root_segment_id IS NOT NULL LIMIT 1), NEW.id) WHERE id=NEW.id; END;
CREATE TRIGGER segments_version AFTER UPDATE OF rule_json,schedule_json,preparation_id,from_slot,before_slot,preparation_not_before ON recurring_schedule_segments
    WHEN NEW.rule_json IS NOT OLD.rule_json OR NEW.schedule_json IS NOT OLD.schedule_json OR NEW.preparation_id IS NOT OLD.preparation_id OR NEW.from_slot IS NOT OLD.from_slot OR NEW.before_slot IS NOT OLD.before_slot OR NEW.preparation_not_before IS NOT OLD.preparation_not_before BEGIN
    UPDATE recurring_schedule_segments SET aggregate_version = COALESCE(aggregate_version,0)+1 WHERE id = (SELECT root_segment_id FROM recurring_schedule_segments WHERE id = NEW.id); END;
CREATE TRIGGER template_delete AFTER DELETE ON preparation_templates BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_template_id=OLD.id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_template_id=OLD.id); END;
CREATE TRIGGER template_steps_delete AFTER DELETE ON preparation_template_steps BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_template_id=OLD.template_id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_template_id=OLD.template_id); END;
CREATE TRIGGER template_steps_insert AFTER INSERT ON preparation_template_steps BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_template_id=NEW.template_id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_template_id=NEW.template_id); END;
CREATE TRIGGER template_steps_update AFTER UPDATE ON preparation_template_steps BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_template_id=NEW.template_id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_template_id=NEW.template_id); END;
CREATE TRIGGER template_update AFTER UPDATE ON preparation_templates BEGIN UPDATE schedules SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE preparation_template_id=OLD.id; UPDATE recurring_schedule_segments SET aggregate_version=COALESCE(aggregate_version,0)+1 WHERE id IN (SELECT r.root_segment_id FROM recurring_schedule_segments r JOIN schedules s ON s.recurring_segment_id=r.id WHERE s.preparation_template_id=OLD.id); END;
CREATE TRIGGER users_identity AFTER INSERT ON users WHEN NEW.store_incarnation IS NULL BEGIN
    UPDATE users SET store_incarnation = lower(hex(randomblob(16))) WHERE id = NEW.id; END;
PRAGMA user_version=3;
